/**
 * Every directory the generators read from or write to, resolved once.
 *
 * There were six spellings of the output root across seven scripts, two
 * conventions for the anchors (`__dirname`/`root` in the older three,
 * `here`/`site` in the newer four), `resolve` and `join` used interchangeably
 * for the same operation, and two different spellings of the sibling repo path
 * — one built with `join`, one by string interpolation.
 *
 * None of that reaches a generated byte, which is exactly why it drifted: no
 * output ever disagreed. What it cost was legibility, and a fifth spelling
 * every time a generator was added.
 */

import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

/** `resolve` to climb out of this file's directory, `join` to descend. */
const here = dirname(fileURLToPath(import.meta.url));

export const scripts = resolve(here, '..');
export const site = resolve(scripts, '..');
export const repo = resolve(site, '..');

export const pkg = join(repo, 'packages/schema');
export const schemaDir = join(pkg, 'schema');
export const mappingsDir = join(pkg, 'mappings');
export const bindingsDir = join(mappingsDir, 'bindings');
export const adrDir = join(repo, 'adr');

export const docs = join(site, 'src/content/docs');
export const docsSchema = join(docs, 'schema');

/**
 * The checkout holding the transform packages, as a sibling of this repo.
 *
 * Two generators read their declared per-element style key tables from here.
 * It is genuinely optional — a clone of this repo alone is a valid checkout —
 * so every read through it is guarded and the pages it feeds degrade to
 * omitting a section rather than failing.
 */
export const transforms = resolve(repo, '../specs-transforms');
